$root=dirname(__DIR__);require_once $root.'/app/bootstrap.php';require_once $root.'/app/MigrationService.php';MigrationService::run();require_once $root.'/app/AuthService.php';require_once $root.'/app/MediaLibraryService.php';require_once $root.'/app/StoryAuthoringService.php';AuthService::boot();$admin=AuthService::requireAdmin();$view=(string)($_GET['view']??'overview');$error=null;$notice=null;$generatedUrl=null;$auditText=null;
if($_SERVER['REQUEST_METHOD']==='POST'){try{AuthService::requireCsrf();$action=(string)($_POST['action']??'');$target=(int)($_POST['user_id']??0);
 if($action==='invite'){$r=AuthService::createInvitation((string)$_POST['email'],(int)$admin['user_id']);$notice=$r['sent']?'Invitation email sent.':'Mail was unavailable; copy the invitation link below.';$generatedUrl=$r['url'];$view='invitations';}
 if($action==='reset_user'){$q=db()->prepare('SELECT email FROM users WHERE user_id=?');$q->execute([$target]);$email=$q->fetchColumn();if(!$email)throw new RuntimeException('User not found.');$r=AuthService::createPasswordResetForEmail((string)$email);$notice=$r&&$r['sent']?'Password-reset email sent.':'Mail was unavailable; copy the reset link below.';$generatedUrl=$r['url']??null;$view='accounts';}
 if($action==='toggle_status'){if($target===(int)$admin['user_id'])throw new RuntimeException('You cannot disable your own account.');db()->prepare('UPDATE users SET status=IF(status="ACTIVE","DISABLED","ACTIVE") WHERE user_id=?')->execute([$target]);$notice='Account status updated.';$view='accounts';}
 if($action==='toggle_admin'){if($target===(int)$admin['user_id'])throw new RuntimeException('You cannot remove your own administrator access.');db()->prepare('UPDATE users SET is_admin=IF(is_admin=1,0,1) WHERE user_id=?')->execute([$target]);$notice='Administrator access updated.';$view='accounts';}
 if($action==='toggle_writer'){$enabled=!AuthService::hasRole($target,'WRITER');AuthService::setRole($target,'WRITER',$enabled,(int)$admin['user_id']);$notice='Story Writer access updated.';$view='accounts';}
 if($action==='review_writer'){AuthService::reviewWriterRequest((int)$_POST['writer_request_id'],(string)$_POST['decision']==='approve',(int)$admin['user_id'],(string)($_POST['reviewer_notes']??''));$notice='Story Writer request reviewed.';$view='writer_requests';}
 if($action==='review_story'){$versionId=(int)$_POST['plot_version_id'];$status=in_array((string)$_POST['decision'],['APPROVED','CHANGES_REQUESTED','PUBLISHED','ARCHIVED'],true)?(string)$_POST['decision']:'CHANGES_REQUESTED';$q=db()->prepare('SELECT plot_id FROM plot_versions WHERE plot_version_id=?');$q->execute([$versionId]);$reviewPlot=(int)$q->fetchColumn();if(!$reviewPlot)throw new RuntimeException('Submitted revision not found.');db()->prepare('UPDATE plot_versions SET workflow_status=?,reviewed_by_user_id=?,review_notes=?,reviewed_at_utc=UTC_TIMESTAMP() WHERE plot_version_id=?')->execute([$status,$admin['user_id'],trim((string)($_POST['review_notes']??''))?:null,$versionId]);db()->prepare('UPDATE plots SET workflow_status=?,status=IF(?="PUBLISHED","active",status) WHERE plot_id=?')->execute([$status,$status,$reviewPlot]);$notice='Story review status updated.';$view='story_reviews';}
 if($action==='audit_story'){$audit=StoryAuthoringService::saveAudit((int)$_POST['plot_id'],(int)$admin['user_id'],(int)($_POST['plot_version_id']??0)?:null);$auditText=$audit['text'];$notice='Story review package generated below.';$view='story_reviews';}
 if($action==='save_theme'){$genreId=(int)$_POST['genre_id'];foreach(['primary_color','secondary_color','accent_color','background_color','surface_color','text_color']as$color)if(!preg_match('/^#[0-9A-Fa-f]{6}$/',(string)$_POST[$color]))throw new RuntimeException('Theme colors must use six-digit hexadecimal values.');$ids=[];$paths=[];foreach(['BACKGROUND','DIVIDER','CARD']as$type){$field=strtolower($type).'_media_id';$id=(int)($_POST[$field]??0);$ids[$type]=$id?:null;$paths[$type]=$id?MediaLibraryService::requireVisible($admin,$id,$type)['file_path']:null;}db()->prepare('UPDATE genre_themes SET primary_color=?,secondary_color=?,accent_color=?,background_color=?,surface_color=?,text_color=?,heading_font=?,body_font=?,background_media_id=?,divider_media_id=?,card_media_id=?,background_image_path=?,divider_image_path=?,card_image_path=?,updated_by_user_id=? WHERE genre_id=?')->execute([$_POST['primary_color'],$_POST['secondary_color'],$_POST['accent_color'],$_POST['background_color'],$_POST['surface_color'],$_POST['text_color'],trim((string)$_POST['heading_font']),trim((string)$_POST['body_font']),$ids['BACKGROUND'],$ids['DIVIDER'],$ids['CARD'],$paths['BACKGROUND'],$paths['DIVIDER'],$paths['CARD'],$admin['user_id'],$genreId]);$notice='Genre theme saved.';$view='themes';}
 if($action==='save_security'){$mode=in_array((string)($_POST['captcha_mode']??''),['BUILTIN','GOOGLE','OFF'],true)?(string)$_POST['captcha_mode']:'BUILTIN';$settings=['SECURITY_CAPTCHA_MODE'=>$mode,'GOOGLE_RECAPTCHA_SITE_KEY'=>trim((string)($_POST['recaptcha_site_key']??''))];if(trim((string)($_POST['recaptcha_secret_key']??''))!=='')$settings['GOOGLE_RECAPTCHA_SECRET_KEY']=trim((string)$_POST['recaptcha_secret_key']);$q=db()->prepare('INSERT INTO platform_settings(setting_key,setting_value,updated_by_user_id) VALUES(?,?,?) ON DUPLICATE KEY UPDATE setting_value=VALUES(setting_value),updated_by_user_id=VALUES(updated_by_user_id)');foreach($settings as$key=>$value)$q->execute([$key,$value,$admin['user_id']]);$notice='Login security settings saved.';$view='security';}
}catch(Throwable$e){$error=$e->getMessage();}}
$counts=['users'=>(int)db()->query('SELECT COUNT(*) FROM users')->fetchColumn(),'human'=>(int)db()->query('SELECT COUNT(*) FROM games')->fetchColumn(),'simulations'=>(int)db()->query('SELECT COUNT(*) FROM simulations')->fetchColumn(),'ratings'=>(int)db()->query('SELECT COUNT(*) FROM story_ratings')->fetchColumn()];
$users=$human=$sims=$invites=[];$detailUser=null;$hosted=$joined=$ratings=[];if($view==='accounts'||$view==='overview'){$q=db()->query('SELECT u.*,COUNT(DISTINCT gh.game_id) hosted_count,COUNT(DISTINCT gp.game_id) joined_count,COUNT(DISTINCT sr.story_rating_id) rating_count,ROUND(AVG(sr.rating),1) average_rating,EXISTS(SELECT 1 FROM user_platform_roles xur JOIN platform_roles xr ON xr.platform_role_id=xur.platform_role_id WHERE xur.user_id=u.user_id AND xr.role_code="WRITER") is_writer FROM users u LEFT JOIN games gh ON gh.host_user_id=u.user_id LEFT JOIN game_players gp ON gp.user_id=u.user_id LEFT JOIN story_ratings sr ON sr.user_id=u.user_id GROUP BY u.user_id ORDER BY u.created_at_utc DESC');$users=$q->fetchAll();}
if($view==='human'){$q=db()->query('SELECT g.*,s.status simulation_status,p.title,p.genre,u.display_name host_name,COUNT(DISTINCT gp.user_id) player_count,ROUND(AVG(sr.rating),1) average_rating,COUNT(DISTINCT sr.story_rating_id) rating_count FROM games g JOIN simulations s ON s.simulation_id=g.simulation_id JOIN plots p ON p.plot_id=s.plot_id JOIN users u ON u.user_id=g.host_user_id LEFT JOIN game_players gp ON gp.game_id=g.game_id LEFT JOIN story_ratings sr ON sr.game_id=g.game_id GROUP BY g.game_id ORDER BY g.created_at_utc DESC');$human=$q->fetchAll();}
if($view==='simulations'||$view==='simulation'){$where=$view==='simulations'?'WHERE g.game_id IS NULL':'';$q=db()->query('SELECT s.simulation_id,s.status,s.current_phase,s.elapsed_seconds,s.created_at_utc,p.title,p.genre,g.game_id,COALESCE(hu.display_name,"System") host_name,COALESCE(cc.human_count,0) human_count,COALESCE(cc.ai_count,0) ai_count,rr.average_rating,COALESCE(rr.rating_count,0) rating_count FROM simulations s JOIN plots p ON p.plot_id=s.plot_id LEFT JOIN games g ON g.simulation_id=s.simulation_id LEFT JOIN users hu ON hu.user_id=g.host_user_id LEFT JOIN (SELECT simulation_id,SUM(controller_type="HUMAN") human_count,SUM(controller_type="AI") ai_count FROM characters GROUP BY simulation_id) cc ON cc.simulation_id=s.simulation_id LEFT JOIN (SELECT game_id,ROUND(AVG(rating),1) average_rating,COUNT(*) rating_count FROM story_ratings GROUP BY game_id) rr ON rr.game_id=g.game_id '.$where.' ORDER BY s.simulation_id DESC LIMIT 250');$sims=$q->fetchAll();}
if($view==='user'){$uid=(int)($_GET['user']??0);$q=db()->prepare('SELECT user_id,email,display_name,is_admin,status,created_at_utc,last_login_at_utc FROM users WHERE user_id=?');$q->execute([$uid]);$detailUser=$q->fetch();if(!$detailUser)throw new RuntimeException('User not found.');$q=db()->prepare('SELECT g.game_id,g.simulation_id,g.status,g.created_at_utc,p.title,p.genre FROM games g JOIN simulations s ON s.simulation_id=g.simulation_id JOIN plots p ON p.plot_id=s.plot_id WHERE g.host_user_id=? ORDER BY g.created_at_utc DESC');$q->execute([$uid]);$hosted=$q->fetchAll();$q=db()->prepare('SELECT g.game_id,g.simulation_id,g.status,g.created_at_utc,p.title,p.genre,u.display_name host_name,c.name character_name FROM game_players gp JOIN games g ON g.game_id=gp.game_id JOIN simulations s ON s.simulation_id=g.simulation_id JOIN plots p ON p.plot_id=s.plot_id JOIN users u ON u.user_id=g.host_user_id LEFT JOIN characters c ON c.character_id=gp.character_id WHERE gp.user_id=? ORDER BY g.created_at_utc DESC');$q->execute([$uid]);$joined=$q->fetchAll();$q=db()->prepare('SELECT sr.rating,sr.review_text,sr.created_at_utc,p.title,p.genre,g.simulation_id FROM story_ratings sr JOIN games g ON g.game_id=sr.game_id JOIN simulations s ON s.simulation_id=g.simulation_id JOIN plots p ON p.plot_id=s.plot_id WHERE sr.user_id=? ORDER BY sr.created_at_utc DESC');$q->execute([$uid]);$ratings=$q->fetchAll();}
if($view==='invitations'){$q=db()->query('SELECT i.*,u.display_name invited_by FROM user_invitations i JOIN users u ON u.user_id=i.invited_by_user_id ORDER BY i.created_at_utc DESC LIMIT 200');$invites=$q->fetchAll();}
$writerRequests=$storyReviews=$themes=[];$themeMedia=[];$security=['SECURITY_CAPTCHA_MODE'=>'BUILTIN','GOOGLE_RECAPTCHA_SITE_KEY'=>'','GOOGLE_RECAPTCHA_SECRET_KEY'=>''];if($view==='writer_requests')$writerRequests=db()->query('SELECT r.*,u.display_name,u.email,reviewer.display_name reviewer_name FROM writer_access_requests r JOIN users u ON u.user_id=r.user_id LEFT JOIN users reviewer ON reviewer.user_id=r.reviewed_by_user_id ORDER BY FIELD(r.status,"PENDING","APPROVED","DECLINED","WITHDRAWN"),r.created_at_utc DESC')->fetchAll();if($view==='story_reviews')$storyReviews=db()->query('SELECT v.*,p.title,p.code,p.workflow_status plot_workflow,u.display_name submitted_by,reviewer.display_name reviewed_by FROM plot_versions v JOIN plots p ON p.plot_id=v.plot_id JOIN users u ON u.user_id=v.submitted_by_user_id LEFT JOIN users reviewer ON reviewer.user_id=v.reviewed_by_user_id ORDER BY FIELD(v.workflow_status,"SUBMITTED","CHANGES_REQUESTED","APPROVED","PUBLISHED","ARCHIVED"),v.created_at_utc DESC')->fetchAll();if($view==='themes'){$themes=db()->query('SELECT g.*,t.* FROM story_genres g JOIN genre_themes t ON t.genre_id=g.genre_id ORDER BY g.sort_order,g.label_text')->fetchAll();$themeMedia=MediaLibraryService::visibleTo($admin);}if($view==='security'){$q=db()->query('SELECT setting_key,setting_value FROM platform_settings WHERE setting_key IN("SECURITY_CAPTCHA_MODE","GOOGLE_RECAPTCHA_SITE_KEY","GOOGLE_RECAPTCHA_SECRET_KEY")');foreach($q->fetchAll()as$row)$security[$row['setting_key']]=$row['setting_value'];}
function csrf_field():string{return'<input type="hidden" name="csrf_token" value="'.e(AuthService::csrfToken()).'">';}
?><!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Toinky Admin</title><style>
:root{font-family:Inter,system-ui,sans-serif;color:#172033;background:#eef2f7}*{box-sizing:border-box}body{margin:0}.layout{display:grid;grid-template-columns:250px 1fr;min-height:100vh}.side{background:#111827;color:#fff;padding:24px 16px}.brand{font-size:22px;font-weight:900;margin-bottom:28px}.group{font-size:11px;text-transform:uppercase;color:#94a3b8;font-weight:800;letter-spacing:.08em;margin:22px 10px 7px}.side a{display:block;color:#e5e7eb;text-decoration:none;padding:9px 10px;border-radius:8px}.side a.active,.side a:hover{background:#374151;color:#fff}.main{padding:28px;min-width:0}.top{display:flex;justify-content:space-between;align-items:center}.top a{color:#4338ca}.cards{display:grid;grid-template-columns:repeat(auto-fit,minmax(170px,1fr));gap:14px}.metric,.panel{background:#fff;border:1px solid #dbe3ec;border-radius:14px;padding:18px}.metric b{font-size:32px;display:block}.panel{margin-top:18px;overflow:auto}.table{width:100%;border-collapse:collapse;font-size:13px}.table th,.table td{text-align:left;border-bottom:1px solid #e5e7eb;padding:10px 7px;vertical-align:top}.btn{border:0;border-radius:8px;background:#4f46e5;color:#fff;padding:8px 11px;font:inherit;font-weight:750;cursor:pointer;text-decoration:none;display:inline-block}.btn.alt{background:#fff;color:#273043;border:1px solid #cbd5e1}.field{display:block;margin:10px 0}.field input,.field textarea,.field select{width:min(480px,100%);display:block;padding:10px;border:1px solid #cbd5e1;border-radius:8px;margin-top:5px}.notice,.error{padding:12px;border-radius:9px;margin:12px 0}.notice{background:#dcfce7;color:#166534}.error{background:#fee2e2;color:#991b1b}.audit{white-space:pre-wrap;background:#111827;color:#f8fafc;padding:16px;border-radius:8px;max-height:560px;overflow:auto;font:12px/1.5 ui-monospace,monospace}.theme-preview{padding:18px;border-radius:10px;margin:10px 0}.url{word-break:break-all;background:#f8fafc;padding:10px;border-radius:8px}.actions form{display:inline}.muted{color:#64748b}@media(max-width:760px){.layout{grid-template-columns:1fr}.side{position:static}.main{padding:18px}}
</style><link rel="stylesheet" href="assets/toinky-theme.css"></head><body><div class="layout"><aside class="side"><div class="toinky-brand-group"><a class="toinky-brand" href="./" aria-label="Toinky home"><span class="toinky-logo-mark" role="img" aria-label="Toinky"></span></a><span class="brand-context">Admin</span></div><div class="group">Accounts</div><a class="<?=$view==='overview'?'active':''?>" href="?view=overview">Overview</a><a class="<?=$view==='accounts'?'active':''?>" href="?view=accounts">Manage Users</a><a class="<?=$view==='invitations'?'active':''?>" href="?view=invitations">Invitations</a><a class="<?=$view==='writer_requests'?'active':''?>" href="?view=writer_requests">Writer Requests</a><div class="group">Gameplay</div><a class="<?=$view==='simulation'?'active':''?>" href="?view=simulation">Simulation View</a><a href="lab.php">Story Engine Lab</a><a href="writer.php">Story Writer</a><div class="group">Story Publishing</div><a class="<?=$view==='story_reviews'?'active':''?>" href="?view=story_reviews">Story Reviews</a><a class="<?=$view==='themes'?'active':''?>" href="?view=themes">Theme Manager</a><div class="group">Stories Played</div><a class="<?=$view==='human'?'active':''?>" href="?view=human">Human Games</a><a class="<?=$view==='simulations'?'active':''?>" href="?view=simulations">Simulation Games</a><div class="group">Site Settings</div><a class="<?=$view==='security'?'active':''?>" href="?view=security">Security</a><div class="group">Account</div><a href="./">Public Portal</a></aside><main class="main"><div class="top"><div><h1><?=e(ucwords(str_replace('_',' ',$view)))?></h1><span class="muted">Signed in as <?=e($admin['display_name'])?></span></div></div><?php if($error):?><div class="error"><?=e($error)?></div><?php endif;?><?php if($notice):?><div class="notice"><?=e($notice)?></div><?php endif;?><?php if($generatedUrl):?><div class="url"><b>Fallback link:</b> <?=e($generatedUrl)?></div><?php endif;?>
<?php if($view==='overview'):?><div class="cards"><div class="metric"><b><?=$counts['users']?></b>Users</div><div class="metric"><b><?=$counts['human']?></b>Hosted games</div><div class="metric"><b><?=$counts['simulations']?></b>Simulations</div><div class="metric"><b><?=$counts['ratings']?></b>Ratings</div></div><section class="panel"><h2>Recent users</h2><?php $users=array_slice($users,0,10);require __DIR__.'/_admin_users_table.php';?></section>
<?php elseif($view==='accounts'):?><section class="panel"><h2>User accounts</h2><?php require __DIR__.'/_admin_users_table.php';?></section>
<?php elseif($view==='user'):?><section class="panel"><h2><?=e($detailUser['display_name'])?></h2><p><?=e($detailUser['email'])?> · <?=e($detailUser['status'])?><?=((int)$detailUser['is_admin']===1)?' · Administrator':''?></p></section><section class="panel"><h2>Stories hosted</h2><table class="table"><tr><th>Story</th><th>Genre</th><th>Status</th><th>Created</th><th>Storyboard</th></tr><?php foreach($hosted as$g):?><tr><td><?=e($g['title'])?></td><td><?=e($g['genre'])?></td><td><?=e($g['status'])?></td><td><?=e($g['created_at_utc'])?></td><td><a href="lab.php?simulation=<?=(int)$g['simulation_id']?>">View</a></td></tr><?php endforeach;?></table></section><section class="panel"><h2>Stories joined</h2><table class="table"><tr><th>Story</th><th>Genre</th><th>Host</th><th>Character</th><th>Status</th><th>Storyboard</th></tr><?php foreach($joined as$g):?><tr><td><?=e($g['title'])?></td><td><?=e($g['genre'])?></td><td><?=e($g['host_name'])?></td><td><?=e($g['character_name']??'Not selected')?></td><td><?=e($g['status'])?></td><td><a href="lab.php?simulation=<?=(int)$g['simulation_id']?>">View</a></td></tr><?php endforeach;?></table></section><section class="panel"><h2>Story ratings</h2><table class="table"><tr><th>Story</th><th>Genre</th><th>Rating</th><th>Review</th><th>Date</th></tr><?php foreach($ratings as$r):?><tr><td><?=e($r['title'])?></td><td><?=e($r['genre'])?></td><td><?=(int)$r['rating']?> / 5</td><td><?=e($r['review_text']??'')?></td><td><?=e($r['created_at_utc'])?></td></tr><?php endforeach;?></table></section>
<?php elseif($view==='invitations'):?><section class="panel"><h2>Invite a user</h2><form method="post"><?=csrf_field()?><input type="hidden" name="action" value="invite"><label class="field">Email address<input type="email" name="email" required></label><button class="btn">Send invitation</button></form></section><section class="panel"><h2>Invitation history</h2><table class="table"><tr><th>Email</th><th>Invited by</th><th>Created</th><th>Expires</th><th>Status</th></tr><?php foreach($invites as$i):?><tr><td><?=e($i['email'])?></td><td><?=e($i['invited_by'])?></td><td><?=e($i['created_at_utc'])?></td><td><?=e($i['expires_at_utc'])?></td><td><?=!empty($i['accepted_at_utc'])?'Accepted':(strtotime($i['expires_at_utc'])<time()?'Expired':'Open')?></td></tr><?php endforeach;?></table></section>
<?php elseif($view==='writer_requests'):?><section class="panel"><h2>Story Writer access requests</h2><p class="muted">New accounts can host and participate in games. Story-building access is granted here after review.</p><table class="table"><tr><th>Applicant</th><th>Request</th><th>Status</th><th>Review</th></tr><?php foreach($writerRequests as$r):?><tr><td><b><?=e($r['display_name'])?></b><br><?=e($r['email'])?><br><span class="muted"><?=e($r['created_at_utc'])?></span></td><td><?=nl2br(e($r['request_text']))?></td><td><?=e(ucwords(strtolower($r['status'])))?><?php if($r['reviewer_name']):?><br><span class="muted">by <?=e($r['reviewer_name'])?></span><?php endif;?></td><td><?php if($r['status']==='PENDING'):?><form method="post"><?=csrf_field()?><input type="hidden" name="action" value="review_writer"><input type="hidden" name="writer_request_id" value="<?=(int)$r['writer_request_id']?>"><label class="field">Notes<textarea name="reviewer_notes" rows="3"></textarea></label><button class="btn" name="decision" value="approve">Approve</button> <button class="btn alt" name="decision" value="decline">Decline</button></form><?php else:?><?=nl2br(e($r['reviewer_notes']??''))?><?php endif;?></td></tr><?php endforeach;?></table><?php if(!$writerRequests):?><p>No access requests yet.</p><?php endif;?></section>
<?php elseif($view==='story_reviews'):?><section class="panel"><h2>Submitted story revisions</h2><p class="muted">Each submission is a fixed revision. Generate the review package before approving or requesting changes.</p><table class="table"><tr><th>Story / revision</th><th>Submitted</th><th>Status</th><th>Audit and decision</th></tr><?php foreach($storyReviews as$r):?><tr><td><b><?=e($r['title'])?></b><br><?=e($r['code'])?> · revision <?=(int)$r['version_no']?></td><td><?=e($r['submitted_by'])?><br><span class="muted"><?=e($r['created_at_utc'])?></span></td><td><?=e(ucwords(strtolower(str_replace('_',' ',$r['workflow_status']))))?><?php if($r['reviewed_by']):?><br><span class="muted">by <?=e($r['reviewed_by'])?></span><?php endif;?></td><td><form method="post" style="margin-bottom:12px"><?=csrf_field()?><input type="hidden" name="action" value="audit_story"><input type="hidden" name="plot_id" value="<?=(int)$r['plot_id']?>"><input type="hidden" name="plot_version_id" value="<?=(int)$r['plot_version_id']?>"><button class="btn alt">Generate audit package</button></form><form method="post"><?=csrf_field()?><input type="hidden" name="action" value="review_story"><input type="hidden" name="plot_version_id" value="<?=(int)$r['plot_version_id']?>"><label class="field">Decision<select name="decision"><option value="CHANGES_REQUESTED">Request changes</option><option value="APPROVED">Approve</option><option value="PUBLISHED">Publish</option><option value="ARCHIVED">Archive</option></select></label><label class="field">Review notes<textarea name="review_notes" rows="4"><?=e($r['review_notes']??'')?></textarea></label><button class="btn">Save review</button></form></td></tr><?php endforeach;?></table><?php if(!$storyReviews):?><p>No submitted revisions yet.</p><?php endif;?></section><?php if($auditText):?><section class="panel"><h2>AI-ready story review package</h2><p>Copy this complete package into an AI reviewer. It includes the scenario, cast, chronology, choices, dependencies, endings, and the required critique criteria.</p><pre class="audit"><?=e($auditText)?></pre></section><?php endif;?>
<?php elseif($view==='themes'):?><section class="panel"><h2>Genre Theme Manager</h2><p class="muted">Every genre starts with its own palette and typography. Images come from the shared Media library; administrators can select any active upload.</p><?php foreach($themes as$t):?><form method="post" class="panel" style="box-shadow:none"><?=csrf_field()?><input type="hidden" name="action" value="save_theme"><input type="hidden" name="genre_id" value="<?=(int)$t['genre_id']?>"><h3><?=e($t['label_text'])?></h3><div class="theme-preview" style="background:<?=e($t['background_color'])?>;color:<?=e($t['text_color'])?>;border:4px solid <?=e($t['accent_color'])?>;font-family:<?=e($t['body_font'])?>"><b style="font-family:<?=e($t['heading_font'])?>;color:<?=e($t['primary_color'])?>">A preview of this genre</b><br>Story prose appears on this surface.</div><div class="cards"><?php foreach(['primary_color'=>'Primary','secondary_color'=>'Secondary','accent_color'=>'Accent','background_color'=>'Background','surface_color'=>'Surface','text_color'=>'Main Content Text']as$key=>$label):?><label class="field"><?=$label?><input type="color" name="<?=$key?>" value="<?=e($t[$key])?>" required></label><?php endforeach;?></div><label class="field">Heading Font Stack<input name="heading_font" value="<?=e($t['heading_font'])?>" required></label><label class="field">Body Font Stack<input name="body_font" value="<?=e($t['body_font'])?>" required></label><?php foreach(['BACKGROUND'=>'Background','DIVIDER'=>'Story Divider','CARD'=>'Card Texture']as$type=>$label):$field=strtolower($type).'_media_id';?><label class="field"><?=$label?> Image<select name="<?=$field?>"><option value="">No image</option><?php foreach($themeMedia as$m):if($m['media_type']!==$type)continue;?><option value="<?=(int)$m['media_id']?>" <?=((int)($t[$field]??0)===(int)$m['media_id'])?'selected':''?>><?=e($m['title_text'].' · '.($m['uploader_name']??'System'))?></option><?php endforeach;?></select></label><?php endforeach;?><button class="btn">Save <?=e($t['label_text'])?> Theme</button></form><?php endforeach;?></section>
<?php elseif($view==='security'):?><section class="panel"><h2>Login CAPTCHA</h2><p class="muted">Built-in CAPTCHA is enabled by default and needs no external account. Google reCAPTCHA is optional and requires both keys.</p><form method="post"><?=csrf_field()?><input type="hidden" name="action" value="save_security"><label class="field">CAPTCHA Mode<select name="captcha_mode"><option value="BUILTIN" <?=$security['SECURITY_CAPTCHA_MODE']==='BUILTIN'?'selected':''?>>Built-in Challenge</option><option value="GOOGLE" <?=$security['SECURITY_CAPTCHA_MODE']==='GOOGLE'?'selected':''?>>Google reCAPTCHA</option><option value="OFF" <?=$security['SECURITY_CAPTCHA_MODE']==='OFF'?'selected':''?>>Off</option></select></label><label class="field">Google Site Key<input name="recaptcha_site_key" value="<?=e($security['GOOGLE_RECAPTCHA_SITE_KEY'])?>"></label><label class="field">Google Secret Key<input type="password" name="recaptcha_secret_key" placeholder="Leave blank to keep the saved secret"></label><button class="btn">Save Security Settings</button></form></section>
